import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

// 1. 定义状态类，继承ChangeNotifier
// 这里我们管理一个简单的计数器和一个名称字符串。
class AppState with ChangeNotifier {
  int _count = 0;
  String _name = '初始名称';

  // 公开的getter，供UI读取
  int get count => _count;
  String get name => _name;

  // 修改状态的方法
  void increment() {
    _count++;
    // 2. 通知所有监听者（即正在使用此状态的Widget）状态已改变
    notifyListeners();
  }

  void changeName(String newName) {
    _name = newName;
    notifyListeners();
  }
}

// 3. 在Widget树的顶部注入Provider
void main() {
  runApp(
    ChangeNotifierProvider(
      create: (context) => AppState(), // 创建AppState实例
      child: const MyApp(),
    ),
  );
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Provider 示例',
      home: Scaffold(
        appBar: AppBar(title: const Text('Provider Demo')),
        body: const Center(child: CounterDisplay()),
        floatingActionButton: const IncrementButton(),
      ),
    );
  }
}

// 4. 使用Consumer来监听状态变化并重建UI
// Consumer是Provider提供的一个便捷Widget，它会在状态变化时自动重建其builder
// 此Widget只关心计数器的值，所以当name变化时，它不会重建，提升了性能。
class CounterDisplay extends StatelessWidget {
  const CounterDisplay({super.key});

  @override
  Widget build(BuildContext context) {
    // 使用Consumer包裹需要依赖状态的Widget
    return Consumer<AppState>(
      builder: (context, appState, child) {
        // appState 就是从Provider树中获取到的AppState实例
        return Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text('计数器值: ${appState.count}', style: const TextStyle(fontSize: 24)),
            const SizedBox(height: 20),
            Text('名称: ${appState.name}', style: const TextStyle(fontSize: 18)),
          ],
        );
      },
    );
  }
}

// 5. 通过context.read()或context.watch()来获取状态并触发操作
// context.watch() 相当于 Consumer，会订阅变化。
// context.read() 仅在事件处理（如onPressed）中使用，不会触发重建，用于调用方法。
class IncrementButton extends StatelessWidget {
  const IncrementButton({super.key});

  @override
  Widget build(BuildContext context) {
    return FloatingActionButton(
      onPressed: () {
        // 使用 context.read() 获取AppState实例并调用方法
        // read不会引起此Widget的重建
        context.read<AppState>().increment();
      },
      tooltip: '增加计数',
      child: const Icon(Icons.add),
    );
  }
}

